style.css:
@-moz-document domain("youtube.com") {
/* Alterar a logo do YouTube */
    #logo-icon-container, #logo {
        background-image: url("https://i.imgur.com/xntyjaB.png") !important;
        background-repeat: no-repeat !important;
        background-size: contain !important;
        width: 120px !important; /* Tamanho da logo */
        height: 30px !important; /* Altura da logo */
    }
    #logo-icon-container svg, #logo svg {
        display: none !important; /* Remove a logo padrão */
    }
}
